def applica_a_listino(D, NUM, P=None):
    """Applica i livelli ai dati di prezzi-dati.py (idempotente)."""
    NUM.update(NUM_NEW)
    for lang, x in LIVELLI_PAGINA.items():
        d = D[lang]
        d['desc'], d['ogdesc'] = x['desc'], x['ogdesc']
        d['svc']['desc'] = x['svc_desc']
        cat = d['cats'][0]
        cat['intro'] = x['intro']
        cat['cards'] = x['cards']
        d['garanzie'] = x['gar']
        # FAQ: prima domanda sostituita, nuove inserite subito dopo
        faq = [f for f in d['faq'] if f[0] not in {q for q, _ in x['faq_add']}]
        faq[0] = x['faq_first']
        d['faq'] = faq[:1] + list(x['faq_add']) + faq[1:]
        # offerte (tabella + JSON-LD)
        off = []
        for o in d['offers']:
            name, desc, key, unit, dur = o
            if key in x['offers_ren']:
                name, desc = x['offers_ren'][key]
            off.append((name, desc, key, unit, dur))
            if key == 'sito_una':
                for n2, d2, k2 in x['offers_add']:
                    off.append((n2, d2, k2, None, None))
        seen = set(); d['offers'] = [o for o in off if not (o[2] in seen or seen.add(o[2]))]
        if d.get('tab'):
            d['tab']['prezzi'].update(x['tab'])
            d['tab']['upd'] = UPD[lang]
        d['ctabox']['p'] = x['ctap']
    return D


